async function submitDevPassword(event){event.preventDefault();if(state.passwordBusy)return;const setup=!state.password.configured,password=$('devPassword').value;if(password.length<12||password.length>128){showFieldError('devPasswordError','Use uma senha de 12 a 128 caracteres.');return;}if(setup&&password!==$('devPasswordConfirm').value){showFieldError('devPasswordError','A confirmação da senha está diferente.');return;}state.passwordBusy=true;$('devPasswordSubmit').disabled=true;showFieldError('devPasswordError','');try{await rawJSON('/api/admin/password/'+(setup?'setup':'unlock'),{method:'POST',headers:{'Content-Type':'application/json','X-Admin-CSRF':state.csrf},body:JSON.stringify({password})});$('devPassword').value='';$('devPasswordConfirm').value='';await refreshSession();}catch(error){if(error.status===401)showGate('Entre novamente na conta ChatGPT autorizada.',{login:true,url:error.data?.signInUrl});else if(error.status===409)await refreshSession();else showFieldError('devPasswordError',error.message);}finally{state.passwordBusy=false;$('devPasswordSubmit').disabled=false;}}
