function updateEditorLabels(){const t=selected();if(!t)return;text('editVolumeValue',Math.round((t.volume??1)*100)+'%');text('editFadeValue',seconds(t.fadeMs??state.config.defaultFadeMs));}
async function playPreview(){try{await $('trackPreview').play();}catch{toast('Não foi possível tocar a prévia. Verifique sua sessão e tente novamente.',true);}}
