function trackOptions(select,selectedId){select.replaceChildren(new Option('Sem música neste contexto',''));for(const c of state.config.categories){const tracks=state.config.tracks.filter(t=>t.categoryId===c.id);if(!tracks.length)continue;const group=document.createElement('optgroup');group.label=c.name;for(const t of tracks.slice().sort((a,b)=>a.title.localeCompare(b.title,'pt-BR')))group.append(new Option(t.title,t.id));select.append(group);}select.value=selectedId||'';}
let bindingScope='all';
const scopeFor=context=>context.id.startsWith('cutscenes.')?'cutscenes':context.group==='Batalhas'?'battles':['Cenários','Salas'].includes(context.group)?'maps':'others';
