  const entries=contexts.filter(c=>String(c.group||'Outros')===group&&(!filter||filter===group)&&(bindingScope==='all'||scopeFor(c)===bindingScope)&&(!query||(c.label+' '+c.id+' '+group).toLocaleLowerCase('pt-BR').includes(query))&&(!only||state.config.bindings[c.id]?.trackId));
