 const actions=el('div','binding-actions'),play=el('button','binding-preview');play.type='button';play.innerHTML=svg('play');play.setAttribute('aria-label','Ouvir trilha de '+context.label);play.disabled=!binding?.trackId;play.addEventListener('click',()=>{selectTrack(binding.trackId,false);playPreview();});
