let syncPreview=null,syncGeneration=0,syncRaf=0;
function preciseTime(value){const n=Math.max(0,Number(value)||0),minutes=Math.floor(n/60),rest=(n-minutes*60).toFixed(2).padStart(5,'0');return String(minutes).padStart(2,'0')+':'+rest;}
function cueValues(preview=syncPreview){if(!preview)return null;const b=preview.binding,t=preview.track;return{start:bounded(b.startSeconds,0,Math.max(0,(t.duration||0)-.01),0),delay:bounded(b.delaySeconds,0,Math.max(0,preview.meta.duration-.01),0),volume:bounded(state.config.masterVolume*(t.volume??1)*(b.volume??1),0,1,.7),fade:(b.fadeMs??t.fadeMs??state.config.defaultFadeMs)/1000,loop:b.loop??t.loop??true};}
function stopSyncPreview(close=true){syncGeneration++;cancelAnimationFrame(syncRaf);syncRaf=0;const p=syncPreview;syncPreview=null;const audio=$('syncMusicAudio');audio.pause();audio.muted=false;audio.removeAttribute('src');audio.load();if(p)p.playing=false;if(close&&$('syncPreviewDialog').open)$('syncPreviewDialog').close();}
function renderSyncFrame(){const p=syncPreview;if(!p)return;try{window.CutscenePreview.render($('syncPreviewCanvas'),p.kind,p.time,{dialogue:true});}catch(error){showFieldError('syncPreviewError','Não foi possível desenhar a cena: '+error.message);pauseSyncScene();}text('syncSceneClock',preciseTime(p.time)+' / '+preciseTime(p.meta.duration));text('syncMusicClock',preciseTime($('syncMusicAudio').currentTime));$('syncSceneTimeline').value=p.time;const shot=p.meta.shots?.find((s,i,a)=>p.time>=s.start&&(i===a.length-1||p.time<a[i+1].start));text('syncShotLabel',shot?.label||p.context.label);$('syncMusicAudio').controls=!p.playing;$('syncScenePlay').textContent=p.playing?'Pausar cena':'Reproduzir cena';$('syncAuditionBtn').textContent=!p.playing&&!$('syncMusicAudio').paused?'Pausar música':'Ouvir trecho da música';}
function expectedMusic(preview=syncPreview){const c=cueValues(preview);if(!preview||!c||preview.time<c.delay)return null;let position=c.start+preview.time-c.delay;const length=Number($('syncMusicAudio').duration)||preview.track.duration;if(length>0&&position>=length){if(!c.loop)return null;const playable=length-c.start;if(playable<=.01)return null;position=c.start+(preview.time-c.delay)%playable;}return{position,volume:c.volume*(c.fade>0?Math.min(1,Math.max(0,(preview.time-c.delay)/c.fade)):1)};}
function synchronizeMusic(force=false){const p=syncPreview,audio=$('syncMusicAudio');if(!p)return;const expected=expectedMusic(p);if(!expected){audio.pause();return;}if(audio.readyState>=1&&(force||Math.abs(audio.currentTime-expected.position)>.22))try{audio.currentTime=expected.position;}catch{}audio.volume=expected.volume;audio.loop=false;if(p.playing&&audio.paused&&!p.starting){p.starting=true;const generation=syncGeneration;audio.play().catch(()=>{if(syncPreview===p&&generation===syncGeneration){showFieldError('syncPreviewError','Toque em Reproduzir cena novamente para liberar o áudio.');pauseSyncScene();}}).finally(()=>{if(syncPreview===p)p.starting=false;});}}
function syncTick(now){const p=syncPreview;if(!p)return;if(p.playing){p.time=Math.min(p.meta.duration,p.time+Math.min(.25,(now-p.last)/1000));if(p.time>=p.meta.duration){p.playing=false;$('syncMusicAudio').pause();}else synchronizeMusic();}p.last=now;renderSyncFrame();syncRaf=requestAnimationFrame(syncTick);}
function primeSyncAudio(){const p=syncPreview,audio=$('syncMusicAudio');if(!p||p.priming)return;const generation=syncGeneration;p.priming=true;audio.muted=true;audio.play().catch(()=>{}).finally(()=>{if(syncPreview===p&&generation===syncGeneration){if(!p.playing||p.time<cueValues(p).delay)audio.pause();audio.muted=false;p.priming=false;}});}
function pauseSyncScene(){if(!syncPreview)return;syncPreview.playing=false;$('syncMusicAudio').pause();renderSyncFrame();}
function seekSyncScene(value){const p=syncPreview;if(!p)return;p.time=bounded(value,0,p.meta.duration,0);p.last=performance.now();if(!p.playing)$('syncMusicAudio').pause();synchronizeMusic(true);renderSyncFrame();}
function updateSyncFields(){const p=syncPreview;if(!p)return;const c=cueValues(p);$('syncStartSeconds').max=Math.max(0,(p.track.duration||0)-.01);$('syncStartSlider').max=Math.max(0,(p.track.duration||0)-.01);$('syncStartSeconds').value=c.start.toFixed(2);$('syncStartSlider').value=c.start;$('syncDelaySeconds').max=Math.max(0,p.meta.duration-.01);$('syncDelaySeconds').value=c.delay.toFixed(2);text('syncCueDescription','A música começa em '+preciseTime(c.start)+' quando a cena chega a '+preciseTime(c.delay)+'.');}
function changeSyncCue(field,value){const p=syncPreview;if(!p)return;const max=field==='startSeconds'?Math.max(0,(p.track.duration||0)-.01):Math.max(0,p.meta.duration-.01);p.binding[field]=Math.round(bounded(value,0,max,0)*100)/100;markDirty();updateSyncFields();if(p.playing)synchronizeMusic(true);else if(field==='startSeconds')try{$('syncMusicAudio').currentTime=p.binding.startSeconds;}catch{}renderSyncFrame();}
function openSyncPreview(context){
 const binding=state.config.bindings[context.id],t=track(binding?.trackId),meta=window.CutscenePreview?.get?.(context.previewKind||context.id);if(!binding||!t||!meta)return;
 stopPreview();syncPreview={context,kind:meta.id,meta,track:t,binding,time:0,playing:false,last:performance.now(),starting:false};text('syncPreviewTitle',context.label);text('syncTrackTitle',t.title);text('syncCueDescription','');showFieldError('syncPreviewError','');$('syncMusicAudio').src=previewURL(t.id);$('syncMusicAudio').preload='auto';$('syncMusicAudio').volume=cueValues().volume;$('syncSceneTimeline').max=meta.duration;
 const marks=$('syncShotMarks');marks.replaceChildren();for(const shot of meta.shots||[]){const b=el('button','sync-shot-mark',preciseTime(shot.start)+' · '+shot.label);b.type='button';b.title=shot.label;b.addEventListener('click',()=>seekSyncScene(shot.start));marks.append(b);}
 updateSyncFields();$('syncPreviewDialog').showModal();renderSyncFrame();syncRaf=requestAnimationFrame(syncTick);
}
$('syncScenePlay').addEventListener('click',()=>{const p=syncPreview;if(!p)return;if(p.playing){pauseSyncScene();return;}showFieldError('syncPreviewError','');if(p.time>=p.meta.duration)p.time=0;p.playing=true;p.last=performance.now();if(!p.playing)$('syncMusicAudio').pause();synchronizeMusic(true);renderSyncFrame();});
$('syncSceneRestart').addEventListener('click',()=>{pauseSyncScene();seekSyncScene(0);});
$('syncSceneTimeline').addEventListener('input',e=>seekSyncScene(e.target.value));
$('syncStartSeconds').addEventListener('change',e=>changeSyncCue('startSeconds',e.target.value));$('syncStartSlider').addEventListener('input',e=>changeSyncCue('startSeconds',e.target.value));$('syncDelaySeconds').addEventListener('change',e=>changeSyncCue('delaySeconds',e.target.value));
$('syncUseMusicTime').addEventListener('click',()=>changeSyncCue('startSeconds',$('syncMusicAudio').currentTime));$('syncUseSceneTime').addEventListener('click',()=>changeSyncCue('delaySeconds',syncPreview?.time||0));
$('syncAuditionBtn').addEventListener('click',async()=>{if(!syncPreview)return;const audio=$('syncMusicAudio');if(!syncPreview.playing&&!audio.paused){audio.pause();renderSyncFrame();return;}pauseSyncScene();try{await audio.play();}catch{showFieldError('syncPreviewError','Não foi possível tocar a faixa. Confira sua sessão e o arquivo MP3.');}renderSyncFrame();});
$('syncMusicAudio').addEventListener('loadedmetadata',()=>{const p=syncPreview;if(!p)return;if(Number.isFinite($('syncMusicAudio').duration)&&$('syncMusicAudio').duration>0)p.audioDuration=$('syncMusicAudio').duration;updateSyncFields();if(p.playing)synchronizeMusic(true);else try{$('syncMusicAudio').currentTime=cueValues().start;}catch{}});
$('syncMusicAudio').addEventListener('error',()=>{if(!syncPreview)return;pauseSyncScene();showFieldError('syncPreviewError','A música não carregou. Confira o MP3 e desbloqueie o painel novamente se a sessão expirou.');});
$('syncPreviewDialog').addEventListener('close',()=>{stopSyncPreview(false);renderBindings();});document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseSyncScene();});
for(const button of document.querySelectorAll('[data-binding-scope]'))button.addEventListener('click',()=>{bindingScope=button.dataset.bindingScope;$('contextGroupFilter').value='';renderBindings();});

function renderSettings(){$('masterVolume').value=Math.round(state.config.masterVolume*100);$('defaultFade').value=state.config.defaultFadeMs;updateSettingsLabels();}
function updateSettingsLabels(){text('masterVolumeValue',Math.round(state.config.masterVolume*100)+'%');text('defaultFadeValue',seconds(state.config.defaultFadeMs));}
function showPage(page,{focus=false}={}){if(!pageNames[page])page='library';state.page=page;for(const key of Object.keys(pageNames))$('page-'+key).hidden=key!==page;for(const nav of document.querySelectorAll('[data-page]')){const active=nav.dataset.page===page;nav.classList.toggle('active',active);if(active)nav.setAttribute('aria-current','page');else nav.removeAttribute('aria-current');}text('pageCrumb',pageNames[page]);history.replaceState(null,'','#'+page);if(page==='bindings')renderBindings();if(page==='history')loadHistory({silent:true});if(focus)$('adminMain').focus();}
function validateDraft(){if(state.config.tracks.length>200)throw new Error('A biblioteca pode ter até 200 faixas.');if(!state.config.categories.length)throw new Error('Crie pelo menos uma categoria.');const categoryIds=new Set(state.config.categories.map(c=>c.id));for(const c of state.config.categories)if(!c.name?.trim())throw new Error('Todas as categorias precisam de um nome.');for(const t of state.config.tracks){if(!t.title?.trim())throw new Error('Dê um nome para todas as trilhas antes de salvar.');if(!categoryIds.has(t.categoryId))throw new Error('A faixa '+t.title+' precisa de uma categoria válida.');}if(totalBytes()>MAX_TOTAL)throw new Error('As músicas ultrapassam o limite de 128 MiB por APK. Substitua ou remova uma faixa.');for(const [id,b]of Object.entries(state.config.bindings)){const t=track(b.trackId);if(!t)throw new Error('A associação '+id+' aponta para uma trilha que não está na biblioteca.');if(b.startSeconds!==undefined&&(!Number.isFinite(b.startSeconds)||b.startSeconds<0||b.startSeconds>=t.duration))throw new Error('O início da música precisa ficar dentro da faixa.');const meta=window.CutscenePreview?.get?.(id);if(b.delaySeconds!==undefined&&(!Number.isFinite(b.delaySeconds)||b.delaySeconds<0||b.delaySeconds>=(meta?.duration||600)))throw new Error('A entrada da música precisa ficar dentro da cutscene.');}}
function commitSaved(result,generation){const saved=normalizeConfig(result);state.baseRevision=saved.revision;if(state.editGeneration===generation){state.config=saved;state.dirty=false;}else state.config.revision=saved.revision;renderAll();}
async function saveConfig(){if(state.saving||!state.config)return;try{validateDraft();state.saving=true;banner('');updateStatus();const generation=state.editGeneration,result=await api('/api/admin/config',{method:'PUT',body:{config:clone(state.config),baseRevision:state.baseRevision}});commitSaved(result,generation);toast(state.dirty?'A revisão foi salva. Você tem novas edições ainda não salvas.':'Alterações salvas. O jogo já pode usar a nova configuração.');await loadHistory({silent:true});}catch(error){handleSaveError(error);}finally{state.saving=false;updateStatus();}}
function handleSaveError(error){const message=error.status===409?'A configuração mudou em outra sessão. Suas edições estão preservadas nesta tela. Recarregue a versão salva antes de continuar.':error.message;banner(message);toast(message,true);if(error.status===409){const button=el('button','text-button','Recarregar configuração salva');button.style.marginLeft='10px';button.addEventListener('click',reloadConfig);$('globalBanner').append(button);}}
async function reloadConfig(){const okay=!state.dirty||await confirmAction('Descartar as edições desta tela?','A biblioteca será recarregada com a última revisão salva no servidor.','Recarregar');if(!okay)return;try{banner('');await loadConfig();toast('Configuração recarregada.');}catch(error){toast(error.message,true);}}
function confirmAction(title,message,label='Confirmar'){return new Promise(resolve=>{if(state.confirmResolve)state.confirmResolve(false);state.confirmResolve=resolve;text('confirmTitle',title);text('confirmMessage',message);text('confirmActionBtn',label);$('confirmDialog').showModal();});}
async function removeSelected(){const t=selected();if(!t)return;const count=Object.values(state.config.bindings).filter(b=>b.trackId===t.id).length,okay=await confirmAction('Excluir “'+t.title+'”?','A trilha sai da biblioteca e '+count+' '+(count===1?'associação será removida':'associações serão removidas')+'. Você precisa salvar para aplicar. APKs já gerados continuam preservados.','Excluir trilha');if(!okay)return;state.config.tracks=state.config.tracks.filter(x=>x.id!==t.id);for(const id of Object.keys(state.config.bindings))if(state.config.bindings[id].trackId===t.id)delete state.config.bindings[id];state.selectedId=null;stopPreview();markDirty();renderAll();toast('Trilha removida desta revisão. Salve para aplicar.');}
function chooseFiles(replaceId=null){if(state.uploading)return;state.replaceId=replaceId;$('mp3Files').multiple=!replaceId;$('mp3Files').value='';$('mp3Files').click();}
function cleanPending(){const audio=$('uploadPreview');audio.pause();audio.removeAttribute('src');audio.load();for(const f of state.pendingFiles)if(f.url)URL.revokeObjectURL(f.url);state.pendingFiles=[];state.pendingIndex=0;state.replaceId=null;}
function validMP3File(file){if(!/\.mp3$/i.test(file.name))return'“'+file.name+'” não é um arquivo .mp3.';if(!file.size)return'“'+file.name+'” está vazio.';if(file.size>MAX_FILE)return'“'+file.name+'” ultrapassa 32 MiB.';if(file.type&&!['audio/mpeg','audio/mp3','audio/x-mp3','audio/mpg','application/octet-stream'].includes(file.type))return'“'+file.name+'” não foi identificado como MP3.';return null;}
function openUpload(files){if(state.uploading)return;const replacing=state.replaceId;cleanPending();state.replaceId=replacing;const chosen=[...files].slice(0,replacing?1:20),errors=chosen.map(validMP3File).filter(Boolean);if(errors.length){toast(errors.join(' '),true);state.replaceId=null;return;}if(!chosen.length)return;const old=track(replacing);state.pendingFiles=chosen.map(file=>({file,url:URL.createObjectURL(file),title:old?.title||file.name.replace(/\.mp3$/i,''),categoryId:old?.categoryId||state.config.categories[0]?.id||'',duration:0}));state.pendingIndex=0;text('uploadTitle',old?'Substituir “'+old.title+'”.':'Ouça antes de adicionar.');text('confirmUploadBtn',old?'Substituir na biblioteca':'Adicionar à biblioteca');showFieldError('uploadError','');$('uploadActivity').hidden=true;renderPendingFiles();$('uploadDialog').showModal();}
function renderPendingFiles(){const list=$('pendingFiles');list.replaceChildren();for(let i=0;i<state.pendingFiles.length;i++){const f=state.pendingFiles[i],button=el('button','pending-file'+(i===state.pendingIndex?' active':''));button.type='button';button.append(el('b',null,f.file.name),el('small',null,bytes(f.file.size)));button.addEventListener('click',()=>{state.pendingIndex=i;renderPendingFiles();});list.append(button);}const f=state.pendingFiles[state.pendingIndex];if(!f)return;$('uploadTrackTitle').value=f.title;fillCategorySelect($('uploadCategory'),f.categoryId);$('uploadPreview').src=f.url;$('uploadPreview').loop=false;text('uploadFileInfo',bytes(f.file.size)+' · MP3 · a validação completa acontece no servidor.');}
async function uploadPending(){if(state.uploading||!state.pendingFiles.length)return;try{for(const f of state.pendingFiles)if(!f.title.trim())throw new Error('Dê um nome para cada música.');state.uploading=true;$('confirmUploadBtn').disabled=true;for(const b of $('uploadDialog').querySelectorAll('[data-close]'))b.disabled=true;updateStatus();showFieldError('uploadError','');$('uploadActivity').hidden=false;const initialCount=state.pendingFiles.length;for(let i=0;i<initialCount;i++){const f=state.pendingFiles[i];text('uploadActivity','Validando e enviando '+(i+1)+' de '+initialCount+': '+f.file.name);const result=await api('/api/admin/tracks',{method:'POST',body:f.file,raw:true,headers:{'Content-Type':'audio/mpeg','X-File-Name':encodeURIComponent(f.file.name)}});if(!result?.track||typeof result.track.id!=='string'||!/^[a-f0-9]{64}$/.test(result.track.id))throw new Error('O servidor não retornou uma faixa válida. Nenhuma associação foi alterada.');const old=track(state.replaceId),t={...result.track,title:f.title.trim(),categoryId:f.categoryId,volume:old?.volume??result.track.volume??1,loop:old?.loop??result.track.loop??true,fadeMs:old?.fadeMs??result.track.fadeMs??state.config.defaultFadeMs};let candidate=state.config.tracks.filter(x=>x.id!==state.replaceId&&x.id!==t.id);candidate.push(t);if(totalBytes({...state.config,tracks:candidate})>MAX_TOTAL)throw new Error('A inclusão de “'+t.title+'” ultrapassaria o limite de 128 MiB por APK. As faixas anteriores foram preservadas.');state.config.tracks=candidate;if(state.replaceId&&state.replaceId!==t.id)for(const b of Object.values(state.config.bindings))if(b.trackId===state.replaceId)b.trackId=t.id;state.selectedId=t.id;markDirty();renderLibrary();}renderAll();$('uploadDialog').close();toast(initialCount===1?'Música adicionada à revisão. Salve para aplicar ao jogo.':initialCount+' músicas adicionadas. Salve para aplicar ao jogo.');}catch(error){showFieldError('uploadError',error.message);toast(error.message,true);renderAll();}finally{state.uploading=false;$('confirmUploadBtn').disabled=false;for(const b of $('uploadDialog').querySelectorAll('[data-close]'))b.disabled=false;$('uploadActivity').hidden=true;updateStatus();}}
function openCategories(){state.categoryDraft=clone(state.config.categories);showFieldError('categoryError','');$('newCategoryName').value='';renderCategories();$('categoryDialog').showModal();}
function renderCategories(){const rows=$('categoryRows');rows.replaceChildren();for(const c of state.categoryDraft){const row=el('div','category-row'),input=el('input');input.type='text';input.maxLength=60;input.value=c.name;input.setAttribute('aria-label','Nome da categoria '+c.name);input.addEventListener('input',()=>c.name=input.value);const count=state.config.tracks.filter(t=>t.categoryId===c.id).length,used=el('small',null,count+' '+(count===1?'faixa':'faixas')),remove=el('button');remove.type='button';remove.innerHTML=svg('trash');remove.setAttribute('aria-label','Excluir categoria '+c.name);remove.addEventListener('click',()=>{if(state.categoryDraft.length<2){showFieldError('categoryError','Mantenha pelo menos uma categoria na biblioteca.');return;}state.categoryDraft=state.categoryDraft.filter(x=>x.id!==c.id);showFieldError('categoryError','');renderCategories();});row.append(input,used,remove);rows.append(row);}}
function addCategory(){const name=$('newCategoryName').value.trim();if(!name){showFieldError('categoryError','Digite o nome da nova categoria.');$('newCategoryName').focus();return;}if(state.categoryDraft.some(c=>c.name.trim().toLocaleLowerCase('pt-BR')===name.toLocaleLowerCase('pt-BR'))){showFieldError('categoryError','Já existe uma categoria com esse nome.');return;}state.categoryDraft.push({id:'cat_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,6),name});$('newCategoryName').value='';showFieldError('categoryError','');renderCategories();}
function applyCategories(){const names=state.categoryDraft.map(c=>c.name.trim().toLocaleLowerCase('pt-BR'));if(names.some(n=>!n)){showFieldError('categoryError','Todas as categorias precisam de um nome.');return;}if(new Set(names).size!==names.length){showFieldError('categoryError','Use nomes diferentes para as categorias.');return;}state.config.categories=state.categoryDraft.map(c=>({...c,name:c.name.trim()}));const ids=new Set(state.config.categories.map(c=>c.id));for(const t of state.config.tracks)if(!ids.has(t.categoryId))t.categoryId=state.config.categories[0].id;markDirty();renderAll();$('categoryDialog').close();toast('Categorias atualizadas nesta revisão. Salve para aplicar.');}
async function startBuild(){if(state.saving||state.uploading||isPending(state.job)||state.capabilities.builder!==true)return;try{validateDraft();state.saving=true;banner('');updateStatus();const generation=state.editGeneration,result=await api('/api/admin/builds',{method:'POST',body:{config:clone(state.config),baseRevision:state.baseRevision}});if(result.config)commitSaved(result.config,generation);if(!result.build?.id)throw new Error('O servidor não retornou um processo de geração válido. Verifique o histórico antes de tentar novamente.');showPage('production',{focus:true});watchBuild(result.build);toast('Configuração salva. A geração do APK começou no servidor.');}catch(error){handleSaveError(error);if(error.status===409)await loadHistory({silent:true});}finally{state.saving=false;updateStatus();}}
function renderBuild(job){state.job=job;$('buildProgress').hidden=!job;if(!job)return;const pending=isPending(job),failed=job.status==='failed',succeeded=job.status==='succeeded';text('buildProgressTitle',succeeded?'Seu novo APK está pronto.':failed?'A geração não foi concluída.':job.status==='queued'?'APK aguardando processamento.':'Gerando APK '+(job.versionName||'')+'…');const badge=$('buildStatusBadge');badge.className='status-badge'+(failed?' failed':succeeded?' succeeded':'');badge.textContent=succeeded?'VERIFICADO':failed?'FALHOU':job.status==='queued'?'NA FILA':'EM PROCESSAMENTO';const current=stages.indexOf(job.stage);for(const li of $('buildStages').children){const index=stages.indexOf(li.dataset.stage);li.classList.toggle('complete',succeeded||index<current);li.classList.toggle('current',pending&&index===current);li.querySelector('i').textContent=succeeded||index<current?'✓':String(index+1);}text('buildDetail',(job.versionName?'Versão '+job.versionName+' · ':'')+(Number.isFinite(Number(job.versionCode))?'Código '+job.versionCode+' · ':'')+'Revisão '+(job.configRevision??state.baseRevision)+(pending&&stageNames[job.stage]?' · '+stageNames[job.stage]:succeeded?' · '+bytes(job.bytes):''));showFieldError('buildError',failed?(job.error||'O servidor informou uma falha ao gerar o APK.')+' A última versão funcional foi preservada.':'');const url=safeDownload(job.apkUrl||job.url);$('buildDownload').hidden=!succeeded||!url;if(url)$('buildDownload').href=url;$('retryBuildBtn').hidden=!failed;updateStatus();}
function watchBuild(job){clearTimeout(state.pollTimer);const generation=++state.pollGeneration;renderBuild(job);if(!isPending(job)){loadHistory({silent:true});return;}const poll=async()=>{if(generation!==state.pollGeneration)return;if(document.hidden){state.pollTimer=setTimeout(poll,2000);return;}try{const data=await api('/api/admin/builds/'+encodeURIComponent(job.id)),next=data?.build||data;renderBuild(next);if(!isPending(next)){if(next.status==='succeeded')toast('Novo APK verificado e disponível para download.');else toast('A geração falhou. A última versão funcional está preservada.',true);await loadHistory({silent:true});return;}}catch(error){text('buildDetail','Não foi possível consultar o processo agora. '+error.message+' A geração continua no servidor.');}state.pollTimer=setTimeout(poll,1500);};state.pollTimer=setTimeout(poll,1000);}
async function loadHistory({silent=false}={}){try{const data=await api('/api/admin/history');state.history={changes:Array.isArray(data?.changes)?data.changes:[],builds:Array.isArray(data?.builds)?data.builds:[],latest:data?.latest||null};renderHistory();const running=state.history.builds.find(isPending);if(running&&(!state.job||!isPending(state.job)))watchBuild(running);return true;}catch(error){if(!silent)toast(error.message,true);return false;}}
function renderHistory(){const {builds,changes,latest}=state.history;const list=$('buildHistory');list.replaceChildren();text('buildHistoryCount',builds.length+' '+(builds.length===1?'versão':'versões'));$('buildHistoryEmpty').hidden=builds.length>0;for(const b of builds.slice().sort((a,c)=>(new Date(c.createdAt).getTime()||0)-(new Date(a.createdAt).getTime()||0))){const row=el('article','history-row'),main=el('div'),top=el('div','history-row-top'),badge=el('span','status-badge'+(b.status==='failed'?' failed':b.status==='succeeded'?' succeeded':''),b.status==='succeeded'?'VERIFICADO':b.status==='failed'?'FALHOU':b.status==='queued'?'NA FILA':'EM PROCESSAMENTO');top.append(el('b',null,'Versão '+(b.versionName||'—')),badge);main.append(top);const meta=el('div','history-row-meta');meta.append(el('span',null,'Código '+(b.versionCode??'—')),el('span',null,'Revisão '+(b.configRevision??'—')),el('span',null,date(b.createdAt)));if(b.bytes)meta.append(el('span',null,bytes(b.bytes)));main.append(meta);if(b.status==='failed')main.append(el('p','history-error',b.error||'A geração não foi concluída.'));if(b.sha256)main.append(el('div','history-hash','SHA-256: '+b.sha256));row.append(main);const url=safeDownload(b.apkUrl||b.url);if(b.status==='succeeded'&&url){const a=el('a','button secondary','Baixar APK ↓');a.href=url;a.download='';row.append(a);}else if(isPending(b)){const button=el('button','button secondary','Acompanhar →');button.type='button';button.addEventListener('click',()=>{showPage('production',{focus:true});watchBuild(b);});row.append(button);}list.append(row);}const changeList=$('changeHistory');changeList.replaceChildren();$('changeHistoryEmpty').hidden=changes.length>0;for(const change of changes){const row=el('article','change-row'),icon=el('i');icon.innerHTML=svg('save');const copy=el('div');copy.append(el('b',null,change.summary||'Configuração salva'),el('small',null,'Revisão '+(change.revision??'—')+(change.actor?' · '+change.actor:'')));const when=el('time',null,date(change.at));row.append(icon,copy,when);changeList.append(row);}const latestUrl=safeDownload(latest?.url||latest?.apkUrl);text('latestVersion',latest?.versionName||'—');text('latestReleaseTitle',latest?.versionName?'Versão '+latest.versionName:'Nenhum APK publicado pelo estúdio.');text('latestReleaseDescription',latest?.versionName?'Código '+latest.versionCode+(latest.bytes?' · '+bytes(latest.bytes):'')+'. Esta versão continua disponível se uma nova geração falhar.':'A última versão válida será mostrada aqui quando o servidor informar sua disponibilidade.');$('latestDownload').hidden=!latestUrl;if(latestUrl)$('latestDownload').href=latestUrl;}
// Event wiring. The client never decides who is an administrator.
renderIcons();for(const b of document.querySelectorAll('[data-page]'))b.addEventListener('click',()=>showPage(b.dataset.page,{focus:true}));for(const b of document.querySelectorAll('[data-close]'))b.addEventListener('click',()=>{if(b.dataset.close==='uploadDialog'&&state.uploading)return;$(b.dataset.close).close();});$('retrySessionBtn').addEventListener('click',()=>refreshSession({initial:!state.config}));$('refreshSessionBtn').addEventListener('click',async()=>{if(await refreshSession())toast('Sessão e disponibilidade atualizadas.');});$('saveBtn').addEventListener('click',saveConfig);$('addTrackBtn').addEventListener('click',()=>chooseFiles());$('emptyAddBtn').addEventListener('click',()=>chooseFiles());$('mp3Files').addEventListener('change',e=>openUpload(e.target.files));$('trackSearch').addEventListener('input',renderLibrary);$('categoryFilter').addEventListener('change',renderLibrary);$('trackEditor').addEventListener('submit',e=>e.preventDefault());$('editTitle').addEventListener('input',e=>editTrack('title',e.target.value));$('editCategory').addEventListener('change',e=>editTrack('categoryId',e.target.value));$('editVolume').addEventListener('input',e=>editTrack('volume',Number(e.target.value)/100));$('editLoop').addEventListener('change',e=>editTrack('loop',e.target.checked));$('editFade').addEventListener('input',e=>editTrack('fadeMs',Number(e.target.value)));$('replaceTrackBtn').addEventListener('click',()=>chooseFiles(state.selectedId));$('deleteTrackBtn').addEventListener('click',removeSelected);$('manageCategoriesBtn').addEventListener('click',openCategories);$('categoryForm').addEventListener('submit',e=>{e.preventDefault();applyCategories();});$('addCategoryBtn').addEventListener('click',addCategory);$('newCategoryName').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();addCategory();}});$('confirmDialog').addEventListener('close',()=>{if(state.confirmResolve){const resolve=state.confirmResolve;state.confirmResolve=null;resolve($('confirmDialog').returnValue==='confirm');}});$('uploadForm').addEventListener('submit',e=>{e.preventDefault();uploadPending();});$('uploadDialog').addEventListener('cancel',e=>{if(state.uploading)e.preventDefault();});$('uploadDialog').addEventListener('close',()=>{if(!state.uploading)cleanPending();});$('uploadTrackTitle').addEventListener('input',e=>{const f=state.pendingFiles[state.pendingIndex];if(f)f.title=e.target.value;});$('uploadCategory').addEventListener('change',e=>{const f=state.pendingFiles[state.pendingIndex];if(f)f.categoryId=e.target.value;});$('uploadPreview').addEventListener('loadedmetadata',()=>{const f=state.pendingFiles[state.pendingIndex];if(f&&Number.isFinite($('uploadPreview').duration)){f.duration=$('uploadPreview').duration;text('uploadFileInfo',bytes(f.file.size)+' · '+duration(f.duration)+' · prévia local');}});$('uploadPreview').addEventListener('error',()=>{if(state.pendingFiles.length)text('uploadFileInfo','A prévia não pôde ser reproduzida. O servidor validará o MP3 ao adicionar.');});$('trackPreview').addEventListener('error',()=>{if(state.selectedId&&$('trackPreview').currentSrc)toast('Não foi possível carregar a prévia. Verifique sua sessão e o arquivo no servidor.',true);});for(const id of ['bindingSearch','contextGroupFilter','onlyAssigned'])$(id).addEventListener(id==='bindingSearch'?'input':'change',renderBindings);$('masterVolume').addEventListener('input',e=>{state.config.masterVolume=Number(e.target.value)/100;markDirty();updateSettingsLabels();setPreviewSettings();});$('defaultFade').addEventListener('input',e=>{state.config.defaultFadeMs=Number(e.target.value);markDirty();updateSettingsLabels();});$('buildBtn').addEventListener('click',startBuild);$('retryBuildBtn').addEventListener('click',startBuild);$('refreshHistoryBtn').addEventListener('click',()=>loadHistory());
$('devPasswordForm').addEventListener('submit',submitDevPassword);$('lockStudioBtn').addEventListener('click',lockStudio);
const drop=$('dropZone');drop.addEventListener('click',()=>chooseFiles());drop.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();chooseFiles();}});for(const event of ['dragenter','dragover'])drop.addEventListener(event,e=>{e.preventDefault();drop.classList.add('dragover');});for(const event of ['dragleave','drop'])drop.addEventListener(event,e=>{e.preventDefault();drop.classList.remove('dragover');});drop.addEventListener('drop',e=>{state.replaceId=null;openUpload(e.dataTransfer.files);});window.addEventListener('beforeunload',e=>{if(state.dirty||state.uploading){e.preventDefault();e.returnValue='';}});window.addEventListener('pagehide',()=>{stopPreview();clearTimeout(state.pollTimer);});
window.AudioAdmin=Object.freeze({getPreviewStatus:()=>syncPreview?{contextId:syncPreview.context.id,sceneTime:syncPreview.time,duration:syncPreview.meta.duration,playing:syncPreview.playing,musicTime:$('syncMusicAudio').currentTime,startSeconds:cueValues().start,delaySeconds:cueValues().delay}:null,getStatus:()=>({authorized:state.authorized,password:{configured:state.password.configured,unlocked:state.password.unlocked},page:state.page,dirty:state.dirty,revision:state.baseRevision,tracks:state.config?.tracks.length||0,bindings:state.config?Object.keys(state.config.bindings).length:0,uploading:state.uploading,saving:state.saving,build:state.job?{id:state.job.id,status:state.job.status,stage:state.job.stage}:null})});
